import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse(`{"title":"麦当劳 McDonald's Corporation","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/麦当劳.md","filePath":"03_companies/麦当劳.md"}`),l={name:"03_companies/麦当劳.md"};function i(n,t,d,s,h,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="麦当劳-mcdonald-s-corporation" tabindex="-1">麦当劳 McDonald&#39;s Corporation <a class="header-anchor" href="#麦当劳-mcdonald-s-corporation" aria-label="Permalink to &quot;麦当劳 McDonald&#39;s Corporation&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>McDonald&#39;s Corporation</td></tr><tr><td>行业</td><td>快餐连锁 / 消费服务</td></tr><tr><td>成立年份</td><td>1940年（餐厅业务1940年起步）</td></tr><tr><td>总部</td><td>伊利诺伊州芝加哥</td></tr><tr><td>伯克希尔持仓</td><td>未纳入核心持仓（长期观察）</td></tr><tr><td>首次关注</td><td>1990年代</td></tr><tr><td>核心商业模式</td><td>特许经营 + 房地产轻资产</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>麦当劳是全球最大的快餐连锁企业，在100多个国家运营数万家餐厅。其商业模式的核心并非简单的餐饮销售，而是**&quot;房地产+品牌&quot;的双重特许经营体系**：</p><ul><li><strong>品牌授权</strong>：向特许经营者授权使用麦当劳品牌，收取特许权使用费</li><li><strong>物业控制</strong>：麦当劳通常拥有或长期租赁餐厅物业，再转租给特许经营者</li><li><strong>标准输出</strong>：通过高度标准化的运营体系，确保全球一致的客户体验</li></ul><p>这种轻资产模式使麦当劳在无需大量资本支出的情况下实现快速扩张，同时将经营风险部分转移给特许经营者。</p><h2 id="投资时间线" tabindex="-1">投资时间线 <a class="header-anchor" href="#投资时间线" aria-label="Permalink to &quot;投资时间线&quot;">​</a></h2><ul><li><strong>1990年代</strong>：巴菲特多次公开表示关注麦当劳，但未买入</li><li><strong>长期观察期</strong>：伯克希尔持续追踪麦当劳的经营数据</li><li><strong>最终决定</strong>：经过多年评估，巴菲特认为估值不足以支撑投资</li><li><strong>2017年后</strong>：市场传言伯克希尔有买入意向，但未得到官方确认</li></ul><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><p>巴菲特对麦当劳的特许经营模式给予了高度认可。他多次在股东信中称赞麦当劳是&quot;真正的特许经营冠军&quot;——麦当劳并不拥有所有餐厅的物业，而是通过租约和特许经营协议控制了庞大的门店网络，这种轻资产模式带来了极高的资本回报率。</p><p>然而，巴菲特迟迟不投资麦当劳的原因主要在于估值。他曾表示，麦当劳的股价在大多数时候都反映了其卓越的经营成果，也就是说，市场并没有给投资者留出足够的安全边际。巴菲特宁愿等待一个更有吸引力的价格，也不愿为一家好公司支付过高的代价。另一个考量是，麦当劳面临日益激烈的快餐竞争，健康饮食趋势对长期品牌价值的侵蚀也令他保持警惕。</p><blockquote><p>&quot;麦当劳是一家卓越的企业，拥有真正的特许经营护城河。但好公司也需要有好价格。如果一家优秀企业的估值已经充分反映了其竞争优势，那么投资者就失去了安全边际。在投资中，耐心等待好价格与挑选好公司同样重要。&quot; — 巴菲特（股东信，1990年代）</p></blockquote><h2 id="未投资的原因分析" tabindex="-1">未投资的原因分析 <a class="header-anchor" href="#未投资的原因分析" aria-label="Permalink to &quot;未投资的原因分析&quot;">​</a></h2><ol><li><strong>估值偏高</strong>：麦当劳作为优质特许经营企业，市场长期给予溢价，股价鲜有低估</li><li><strong>竞争优势有限扩散</strong>：汉堡快餐赛道竞争激烈，护城河宽度不如<a href="/03_companies/可口可乐.html">可口可乐</a></li><li><strong>健康趋势风险</strong>：消费者对快餐的负面认知长期存在，品牌面临形象挑战</li><li><strong>耐心等待原则</strong>：宁可错过，不愿买贵——这正是巴菲特的一贯风格</li></ol><h2 id="相关公司" tabindex="-1">相关公司 <a class="header-anchor" href="#相关公司" aria-label="Permalink to &quot;相关公司&quot;">​</a></h2><ul><li><a href="/03_companies/可口可乐.html">可口可乐</a> — 同样拥有强品牌特许经营护城河，是伯克希尔成功持仓案例</li><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> — 巴菲特主阵地，持续评估全球优质企业</li><li><a href="/03_companies/GEICO.html">GEICO</a> — 伯克希尔旗下保险公司，代表另一类轻资产商业模式</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1996年/翻译.html">/01_letters/1996年/翻译</a></li><li><a href="/01_letters/1998年/翻译.html">/01_letters/1998年/翻译</a></li></ul>',20)])])}const _=a(l,[["render",i]]);export{p as __pageData,_ as default};
